      [39.044, 43.107, "Under vanlige modellforutsetninger presses profitten da mot null på lang sikt."],
      [43.267, 49.432, "Det betyr at inntektene dekker alle kostnader, inkludert den normale verdien av kapital og arbeid i beste alternativ."],
      [50.132, 53.255, "Et monopol møter markedets etterspørsel alene."],
      [53.415, 57.804, "Det kan ha markedsmakt, men møter fortsatt en grense i kundenes betalingsvillighet."],
      [57.964, 65.51, "Et naturlig monopol kan oppstå der én leverandør kan betjene hele markedet til lavere kostnad enn flere, for eksempel fordi det er dyrt å bygge parallelle vannnett."],
      [65.67, 70.987, "Regulering handler da blant annet om å veie finansiering og investeringsbehov mot kundenes pris og kvalitet."],
      [71.687, 76.831, "Ved monopolistisk konkurranse gjør produktforskjeller at hver selger kan ha et visst handlingsrom i prisen."],
      [76.991, 80.892, "En kafé kan ta betalt for god beliggenhet eller et tilbud kundene foretrekker."],
      [81.052, 85.963, "Hvis den hever prisen mye, kan kundene gå til andre kaféer, kjøpe på jobb eller lage kaffe hjemme."],
      [86.123, 90.36, "Konkurranse handler også om åpningstid, service og hvor lenge folk må vente."],
      [91.06, 95.344, "I et oligopol er de største konkurrentene få nok til at hver må regne med de andres reaksjon."],
      [95.504, 101.774, "Hvis ett flyselskap dobler kapasiteten, kan det andre redusere prisene, trekke kapasitet eller endre avgangstidene."],
      [101.934, 105.289, "Effekten av den opprinnelige beslutningen avhenger av responsen."],
      [105.449, 111.939, "Etableringshindre som konsesjoner, nettverkseffekter eller store investeringer kan gjøre antallet konkurrenter stabilt over tid."],
      [112.639, 115.704, "Prøv å definere ditt eget marked fra kundens ståsted."],
      [115.864, 119.277, "Hvilke alternativer vurderer kunden ved en liten, varig prisøkning?"],
      [119.437, 123.605, "En kafé ved en stasjon konkurrerer kanskje med bakeriet og kiosken på samme stasjon."],
      [123.765, 126.912, "For en planlagt lunsj kan kundene være villige til å reise lenger."],
      [127.072, 129.846, "Begge kan være relevante, avhengig av beslutningen."],
      [130.546, 133.681, "Bruk markedsstrukturen til å stille konkrete spørsmål."],
      [133.841, 135.362, "Hvor lett er det å bytte?"],
      [135.522, 137.728, "Hvor lett kan en konkurrent etablere seg?"],
      [137.888, 140.489, "Hvor raskt kan eksisterende rivaler reagere?"],
      [140.649, 144.004, "Nå skal vi se hvordan den siste vurderingen kan gjøres systematisk."]
