      [90.035, 95.469, "En uinformert aktør kan på sin side sortere, for eksempel ved å kreve en uavhengig tilstandsrapport."],
      [95.629, 100.586, "Et forsikringsselskap kan tilby avtaler med forskjellige kombinasjoner av premie og egenandel."],
      [100.746, 106.632, "Hvilken avtale kundene velger, kan gi informasjon om risikoen deres, hvis valget faktisk henger sammen med risiko."],
      [107.332, 110.421, "Tenk på bonusen til selgerne i din egen virksomhet."],
      [110.581, 114.946, "Hvis du bare måler nysalg, gir du selgerne en grunn til å prioritere signaturer."],
      [115.106, 119.889, "Måler du også fornyelse og klager, blir det viktigere å selge til kunder som får verdi av produktet."],
      [120.049, 125.552, "Flere måltall kan likevel skape mer administrasjon eller nye muligheter til å tilpasse atferden til målingen."],
      [125.712, 131.784, "Spør derfor hva partene vet før avtalen, hva de kan påvirke etterpå, og hvilke konsekvenser du faktisk kan observere."]
